     1→/**
     2→ * FreeWire Phase 8 — Repair History
     3→ *
     4→ * 시스템이 실수를 기억한다.
     5→ *
     6→ * 매 수정마다 이력을 저장하고,
     7→ * "이 노드 조합에서 이 위반이 n번 발생했다"는 패턴을 축적한다.
     8→ *
     9→ * 이 기억이 두 가지에 쓰인다:
    10→ *   1. PatternAdvisor — 다음 그래프 생성 전 사전 경고
    11→ *   2. AdaptiveWeights — 패치 신뢰도 보정 (자주 통한 패치 우선)
    12→ */
    13→
    14→'use strict';
    15→
    16→// ─── 이력 항목 ───────────────────────────────────────────────
    17→
    18→class RepairRecord {
    19→  constructor({ sessionId, timestamp, violation, patch, resultScore, improved }) {
    20→    this.sessionId   = sessionId;
    21→    this.timestamp   = timestamp ?? Date.now();
    22→    this.violation   = violation;   // { type, fact, repairHint, nodeSubtype }
    23→    this.patch       = patch;       // { type, description, confidence }
    24→    this.resultScore = resultScore; // 패치 적용 후 점수
    25→    this.improved    = improved;    // 점수가 올랐나?
    26→  }
    27→}
    28→
    29→// ─── RepairHistory ──────────────────────────────────────────
    30→
    31→class RepairHistory {
    32→  constructor(maxRecords = 500) {
    33→    this._records   = [];      // RepairRecord[]
    34→    this._maxRecords = maxRecords;
    35→
    36→    // 패턴 인덱스: "subtype:fact" → { count, improvedCount, lastSeen }
    37→    this._patternIndex = new Map();
    38→
    39→    // 패치 효능 인덱스: "patchType:repairHint" → { applied, improved }
    40→    this._efficacyIndex = new Map();
    41→  }
    42→
    43→  // ─── 기록 ──────────────────────────────────────────────
    44→
    45→  record(sessionId, violation, patch, resultScore, previousScore) {
    46→    const improved = resultScore > previousScore;
    47→
    48→    const rec = new RepairRecord({
    49→      sessionId,
    50→      violation: {
    51→        type:        violation.type,
    52→        fact:        violation.fact,
    53→        repairHint:  violation.repairHint,
    54→        nodeSubtype: violation.nodeSubtype ?? null,
    55→      },
    56→      patch: patch ? {
    57→        type:        patch.type,
    58→        description: patch.description,
    59→        confidence:  patch.confidence,
    60→      } : null,
    61→      resultScore,
    62→      improved,
    63→    });
    64→
    65→    this._records.push(rec);
    66→    if (this._records.length > this._maxRecords) {
    67→      this._records.shift(); // 오래된 기록 제거
    68→    }
    69→
    70→    this._updatePatternIndex(rec);
    71→    this._updateEfficacyIndex(rec);
    72→
    73→    return rec;
    74→  }
    75→
    76→  // ─── 패턴 조회 ─────────────────────────────────────────
    77→
    78→  /**
    79→   * 특정 (subtype, fact) 조합이 과거에 몇 번 위반됐는지
    80→   */
    81→  patternCount(nodeSubtype, fact) {
    82→    const key = `${nodeSubtype ?? '*'}:${fact}`;
    83→    return this._patternIndex.get(key)?.count ?? 0;
    84→  }
    85→
    86→  /**
    87→   * 가장 자주 발생하는 위반 패턴 top N
    88→   */
    89→  topViolations(n = 5) {
    90→    return [...this._patternIndex.entries()]
    91→      .map(([key, v]) => ({ pattern: key, ...v }))
    92→      .sort((a, b) => b.count - a.count)
    93→      .slice(0, n);
    94→  }
    95→
    96→  /**
    97→   * 특정 repairHint에 대한 패치 효능 (0-1)
    98→   * 적용 횟수 대비 개선 횟수
    99→   */
   100→  patchEfficacy(patchType, repairHint) {
   101→    const key = `${patchType}:${repairHint}`;
   102→    const e = this._efficacyIndex.get(key);
   103→    if (!e || e.applied === 0) return 0.5; // 기본값
   104→    return e.improved / e.applied;
   105→  }
   106→
   107→  /**
   108→   * 과거 이력에서 이 위반을 가장 잘 고쳤던 패치 타입
   109→   */
   110→  bestPatchFor(repairHint) {
   111→    let best = null, bestScore = -1;
   112→
   113→    for (const [key, e] of this._efficacyIndex.entries()) {
   114→      if (!key.endsWith(`:${repairHint}`)) continue;
   115→      const score = e.applied > 0 ? e.improved / e.applied : 0;
   116→      if (score > bestScore) {
   117→        bestScore = score;
   118→        best = { patchType: key.split(':')[0], efficacy: score, applied: e.applied };
   119→      }
   120→    }
   121→
   122→    return best;
   123→  }
   124→
   125→  /**
   126→   * 세션별 이력 요약
   127→   */
   128→  sessionSummary(sessionId) {
   129→    const recs = this._records.filter(r => r.sessionId === sessionId);
   130→    if (recs.length === 0) return null;
   131→
   132→    return {
   133→      sessionId,
   134→      totalPatches: recs.length,
   135→      improved:     recs.filter(r => r.improved).length,
   136→      finalScore:   recs[recs.length - 1]?.resultScore ?? 0,
   137→      violations:   [...new Set(recs.map(r => r.violation.fact))],
   138→    };
   139→  }
   140→
   141→  /**
   142→   * 전체 통계
   143→   */
   144→  stats() {
   145→    const total    = this._records.length;
   146→    const improved = this._records.filter(r => r.improved).length;
   147→    return {
   148→      totalRecords:   total,
   149→      improvedCount:  improved,
   150→      successRate:    total > 0 ? Math.round((improved / total) * 100) : 0,
   151→      uniquePatterns: this._patternIndex.size,
   152→      topViolations:  this.topViolations(3),
   153→    };
   154→  }
   155→
   156→  /**
   157→   * 직렬화 (저장/복원용)
   158→   */
   159→  toJSON() {
   160→    return {
   161→      records:      this._records,
   162→      patternIndex: [...this._patternIndex.entries()],
   163→      efficacyIndex:[...this._efficacyIndex.entries()],
   164→    };
   165→  }
   166→
   167→  static fromJSON(json) {
   168→    const h = new RepairHistory();
   169→    h._records       = json.records.map(r => Object.assign(new RepairRecord(r), r));
   170→    h._patternIndex  = new Map(json.patternIndex);
   171→    h._efficacyIndex = new Map(json.efficacyIndex);
   172→    return h;
   173→  }
   174→
   175→  // ─── 내부 인덱스 갱신 ──────────────────────────────────
   176→
   177→  _updatePatternIndex(rec) {
   178→    const key = `${rec.violation.nodeSubtype ?? '*'}:${rec.violation.fact}`;
   179→    const prev = this._patternIndex.get(key) ?? { count: 0, improvedCount: 0, lastSeen: 0 };
   180→    this._patternIndex.set(key, {
   181→      count:        prev.count + 1,
   182→      improvedCount:prev.improvedCount + (rec.improved ? 1 : 0),
   183→      lastSeen:     rec.timestamp,
   184→    });
   185→  }
   186→
   187→  _updateEfficacyIndex(rec) {
   188→    if (!rec.patch) return;
   189→    const key = `${rec.patch.type}:${rec.violation.repairHint}`;
   190→    const prev = this._efficacyIndex.get(key) ?? { applied: 0, improved: 0 };
   191→    this._efficacyIndex.set(key, {
   192→      applied: prev.applied + 1,
   193→      improved: prev.improved + (rec.improved ? 1 : 0),
   194→    });
   195→  }
   196→}
   197→
   198→module.exports = { RepairHistory, RepairRecord };
   199→

