   577→
   578→class LayoutEngine {
   579→  /**
   580→   * 노드 목록 + 엣지 → 위치 자동 계산
   581→   * 레이어 기반 배치: 데이터 → 로직 → 컴포넌트 순
   582→   */
   583→  layout(nodes, edges, offsetX = 100, offsetY = 80) {
   584→    const W = 200, H = 140, GAP_X = 60, GAP_Y = 30;
   585→
   586→    const layers = {
   587→      data:      nodes.filter(n => n.type === 'data'),
   588→      logic:     nodes.filter(n => n.type === 'logic'),
   589→      component: nodes.filter(n => n.type === 'component'),
   590→    };
   591→
   592→    const result = {};
   593→    let baseX = offsetX;
   594→
   595→    for (const [layer, layerNodes] of Object.entries(layers)) {
   596→      if (!layerNodes.length) continue;
   597→
   598→      layerNodes.forEach((n, i) => {
   599→        result[n.id] = {
   600→          x: baseX,
   601→          y: offsetY + i * (H + GAP_Y),
   602→        };
   603→      });
   604→
   605→      baseX += W + GAP_X;
   606→    }
   607→
   608→    return result;
   609→  }
   610→
   611→  /**
   612→   * 기존 노드 위치에서 겹치지 않는 위치 찾기
   613→   */
   614→  findFreePosition(existingPositions, nodeCount) {
   615→    const W = 200, H = 140, GAP = 40;
   616→    const cols = Math.ceil(Math.sqrt(nodeCount));
   617→    const positions = [];
   618→
   619→    for (let i = 0; i < nodeCount; i++) {
   620→      const col = i % cols;
   621→      const row = Math.floor(i / cols);
   622→      const baseX = 600 + col * (W + GAP);
   623→      const baseY = 80 + row * (H + GAP);
   624→      positions.push({ x: baseX, y: baseY });
   625→    }
   626→
   627→    return positions;
   628→  }
   629→}
   630→
   631→// ─── 메인 AI 노드 생성기 ─────────────────────────────────────────
   632→
   633→class AINodeGenerator {
   634→  constructor() {
   635→    this.parser = new IntentParser();
   636→    this.templates = new TemplateEngine();
   637→    this.layout = new LayoutEngine();
   638→
   639→    // LLM 브릿지 (선택적)
   640→    this.llmEndpoint = null;
   641→  }
   642→
   643→  /**
   644→   * 텍스트 → 그래프 JSON
   645→   * @param {string} text - 자연어 설명
   646→   * @param {{ offsetX?, offsetY?, existingNodes? }} opts
   647→   * @returns {{ nodes: object, edges: object[], label: string, intent: string }}
   648→   */
   649→  async generate(text, opts = {}) {
   650→    // 1) 의도 파악
   651→    const intent = this.parser.parse(text);
   652→
   653→    // 2) LLM 있으면 시도
   654→    if (this.llmEndpoint) {
   655→      try {
   656→        const llmResult = await this._callLLM(text);
   657→        if (llmResult) return this._finalize(llmResult, opts, intent.type);
   658→      } catch { /* LLM 실패 시 규칙 기반으로 폴백 */ }
   659→    }
   660→
   661→    // 3) 템플릿/규칙 기반 생성
   662→    const raw = this.templates.generate(intent);
   663→
   664→    return this._finalize(raw, opts, intent.type);
   665→  }
   666→
   667→  _finalize(raw, opts, intentType) {
   668→    const { offsetX = 100, offsetY = 80 } = opts;
   669→
   670→    // 위치 계산
   671→    const positions = this.layout.layout(raw.nodes, raw.edges, offsetX, offsetY);
   672→
   673→    // 노드 객체화
   674→    const nodes = {};
   675→    for (const n of raw.nodes) {
   676→      nodes[n.id] = {
   677→        ...n,
   678→        position: positions[n.id] ?? { x: offsetX, y: offsetY },
   679→      };
   680→    }
   681→
   682→    // 엣지 ID 부여
   683→    const edges = raw.edges.map((e, i) => ({ id: e.id ?? `ae-${i}`, ...e }));
   684→
   685→    return {
   686→      nodes,
   687→      edges,
   688→      label: raw.label,
   689→      intent: intentType,
   690→      nodeCount: raw.nodes.length,
   691→      edgeCount: edges.length,
   692→    };
   693→  }
   694→
   695→  /**
   696→   * LLM API 연동 (로컬 서버 or Claude API)
   697→   */
   698→  async _callLLM(text) {
   699→    const SYSTEM = `You are a FreeWire node graph generator.
   700→Given a UI description, return a JSON graph with nodes and edges.
   701→Node types: component (button/text/input/card/container), data (state/const/array), logic (handler/setState/condition).
   702→Return only valid JSON: { "nodes": [...], "edges": [...], "label": "..." }`;
   703→
   704→    const res = await fetch(this.llmEndpoint, {
   705→      method: 'POST',
   706→      headers: { 'Content-Type': 'application/json' },
   707→      body: JSON.stringify({ system: SYSTEM, message: text }),
   708→    });
   709→
   710→    if (!res.ok) throw new Error('LLM API error');
   711→    const data = await res.json();
   712→
   713→    // 응답에서 JSON 추출
   714→    const jsonMatch = (data.content ?? data.text ?? '').match(/\{[\s\S]*\}/);
   715→    if (!jsonMatch) throw new Error('No JSON in LLM response');
   716→    return JSON.parse(jsonMatch[0]);
   717→  }
   718→
   719→  /**
   720→   * LLM 서버 설정
   721→   */
   722→  setLLMEndpoint(url) {
   723→    this.llmEndpoint = url;
   724→  }
   725→
   726→  /**
   727→   * 지원 의도 목록
   728→   */
   729→  getSupportedIntents() {
   730→    return [
   731→      { intent: 'login', example: '로그인 폼 만들어줘' },
   732→      { intent: 'register', example: '회원가입 폼' },
   733→      { intent: 'counter', example: '카운터 앱' },
   734→      { intent: 'search', example: '검색 UI' },
   735→      { intent: 'todo', example: '할 일 리스트' },
   736→      { intent: 'profile-card', example: '프로필 카드' },
   737→      { intent: 'comment-form', example: '댓글 폼' },
   738→      { intent: 'checkout', example: '결제 폼' },
   739→      { intent: 'settings', example: '설정 페이지' },
   740→      { intent: 'dashboard', example: '대시보드' },
   741→      { intent: 'modal', example: '모달 팝업' },
   742→      { intent: 'navbar', example: '네비게이션 바' },
   743→      { intent: 'single-button', example: '버튼 하나만' },
   744→      { intent: 'single-card', example: '카드 UI' },
   745→      { intent: 'input-form', example: '입력 폼' },
   746→    ];
   747→  }
   748→}
   749→
   750→module.exports = { AINodeGenerator, IntentParser, TemplateEngine, LayoutEngine };
